/**
 * DiagnosticsCollector - Gathers diagnostic information from the target node.
 * Intended to be used as an Object Tool (server-script type).
 *
 * Parameters:
 *   $1 - output format: 'text' (default), 'json', or 'csv'
 */

local node = $node;
local format = ($1 != null) ? $1 : 'text';

local diag = {
  'node': node.name,
  'ipAddress': node.ipAddr,
  'status': node.statusText,
  'agentConnected': node.isAgent,
  'snmpEnabled': node.isSNMP,
  'lastPollTime': FormatDate(node.lastStatusPoll, '%Y-%m-%d %H:%M:%S')
};

if (node.isAgent)
{
  diag['cpuUsage'] = AgentGetParameterValue(node, 'System.CPU.Usage');
  diag['memUsedPct'] = AgentGetParameterValue(node, 'System.Memory.Physical.UsedPerc');
  diag['uptime'] = AgentGetParameterValue(node, 'System.Uptime');
  diag['agentVersion'] = AgentGetParameterValue(node, 'Agent.Version');
}

if (format == 'json')
{
  return JsonEncode(diag);
}
else if (format == 'csv')
{
  local csv = 'Key,Value\n';
  foreach (k, v : diag)
    csv = csv + k + ',' + v + '\n';
  return csv;
}
else
{
  local text = 'Diagnostics for ' + node.name + '\n';
  text = text + '================================\n';
  foreach (k, v : diag)
    text = text + k + ': ' + v + '\n';
  return text;
}
